      "--model",
      "smoke-model",
      "--thinking",
      "medium",
      "--tui-mode",
      options.mode,
      "--use-theme",
      options.theme,
    ];
    const command = `stty cols 140 rows 30; exec ${args.map(quote).join(" ")}`;
