      join(packageDir, manifest.bin.pi),
      "--mode",
      "rpc",
      "--no-extensions",
      "--no-skills",
      "--no-prompt-templates",
      "--no-context-files",
      "--offline",
      "--session-dir",
      join(scratch, "sessions"),
      "-e",
      entry,
      "--provider",
      "exa-proto",
      "--model",
      "scripted",
      "--thinking",
      "off",
    ];
