    note: "Prepare",
    thought_number: 1,
    total_thoughts: 1,
    next_step_needed: false,
    executionPlan: {
      goal: "answer",
      taskSchema: {
        type: "object",
        required: ["answer"],
        properties: { answer: { type: "string" } },
        additionalProperties: false,
      },
    },
  });
