    topic: "topic",
    stage: "framing",
    note: "",
    thought_number: number,
    total_thoughts: 2,
    next_step_needed: true,
    executionPlan: { goal, taskSchema: { type: "object" } },
  });
  expect((await pi.call("exa_research_step", step(1, "OLD GOAL"))).isError).not.toBe(true);
