100	function view(record: ResearchCycle) {
101	  const { owner: _owner, ...visible } = record;
102	  const planningStatus = createResearchPlanner(record.plan).getStatus();
103	  let accounting: Record<string, unknown>;
104	  try {
105	    accounting = summarizeAccounting(record.grants, record.ledger, { cycleId: record.id, projectId: record.projectId });
106	  } catch (error) {
107	    accounting = {
108	      ledgerHealthy: false,
109	      assessmentOnly: true,
110	      billingVerified: false,
111	      reason: "UNKNOWN_LIABILITY",
112	      error: error instanceof Error ? error.message : String(error),
113	    };
114	  }
115	  const facts = retryAttemptFacts(record.attempts, record.ledger, { cycleId: record.id, projectId: record.projectId });
116	  const completedIds = facts.filter((fact) => fact.state === "completed").map((fact) => fact.id);
117	  const duplicateSuccess = completedIds.length > 1;
118	  const nextSafeAction =
119	    record.status === "completed" || completedIds.length
120	      ? `${duplicateSuccess ? "Review all duplicate successes and their separate costs. " : ""}Completion blocks further submissions; findings do not satisfy criteria automatically. Inspect the same saved attempt to recover failed local output processing.`
121	      : facts.some((fact) => fact.state === "live")
122	        ? "Existing local research remains live. Inspect the same saved Agent attempt; do not retry or replace live work."
123	        : facts.some((fact) => fact.state === "unclassified")
124	          ? "Legacy attempt has no frozen recovery contract. Inspect its original history manually; never submit automatic replacement research."
125	          : facts.some((fact) => fact.state === "unknown")
126	            ? "Preserve unknown original work and liabilities. No saved remote ID means the original remains unknown. Recover saved remote IDs with researchMode=recover. Any explicit researchMode=replace needs operator approve-replacement for EVERY unknown original, new exact-request funding and total exposure approval. No automatic replacement."
127	            : facts.length
128	              ? "Confirmed failure or proven nondispatch is retained. Revise and preview the draft; explicit researchMode=retry requires new exact-request funding and current total exposure approval. No automatic resubmission."
129	              : "Update the plan and preview the compiled request. Only operator grants and fresh request assessments can authorize spending.";
130	  const pausedMonitors = (record.monitors ?? []).filter((monitor) => monitor.state === "paused");
131	  const monitoringGuidance = pausedMonitors.length
132	    ? ` Background monitoring is paused for ${pausedMonitors.map((monitor) => `attempt ${monitor.attemptId} (${monitor.reason ?? "unknown reason"})`).join(", ")}: the remote run and its liability continue; explicitly resume the cycle or inspect the same attempt with researchMode=recover. Monitoring never creates, retries, replaces or cancels research.`
133	    : "";
134	  const completionSummary = { remoteCompletedAttemptIds: completedIds, duplicateSuccess };
135	  const finalReport =
136	    record.status === "completed"
137	      ? {
138	          cycleId: record.id,
139	          status: record.status,
140	          completionSummary,
141	          recordedCriteria: planningStatus.criteria,
142	          criteriaRequiringReview: planningStatus.criteria.filter(
143	            (criterion) =>
144	              (criterion.status !== "supported" && criterion.status !== "excluded") ||
145	              criterion.evidenceIssues.length > 0,
146	          ),
147	          recordedGaps: record.plan.gaps,
148	          assumptions: record.plan.assumptions,
149	          automaticCriterionSatisfaction: false,
150	          usage: accounting,
151	          nextSafeAction,
152	          furtherResearchRequiresNewCycleAndOperatorPermission: true,
153	        }
154	      : undefined;
155	  return {
156	    ...visible,
157	    ...planningStatus,
158	    accounting,
159	    nextSafeAction: `${nextSafeAction}${monitoringGuidance}`,
160	    completionSummary,
161	    ...(finalReport ? { finalReport } : {}),
162	  };
163	}
