255	    if (entry.timer) clearTimeout(entry.timer);
256	    scheduled.delete(monitorKey(entry.cycleId, entry.attemptId));
257	    try {
258	      await entry.cycles.updateMonitor(entry.cycleId, entry.attemptId, (monitor) => {
259	        if (monitor.state === "stopped" || monitor.state === "paused") return;
260	        monitor.state = "paused";
261	        monitor.reason = reason;
262	      });
263	    } catch {
264	      /* Pausing is best effort; a stale or unreadable record never spawns new work. */
265	    }
266	  };
267	  const pauseAllMonitors = async (reason: MonitorPauseReason) => {
268	    shuttingDown = true;
269	    await Promise.all([...scheduled.values()].map((entry) => pauseMonitor(entry, reason)));
270	  };
271	  const pauseCycleMonitors = async (cycleId: string, reason: MonitorPauseReason) => {
272	    await Promise.all(
273	      [...scheduled.values()].filter((entry) => entry.cycleId === cycleId).map((entry) => pauseMonitor(entry, reason)),
274	    );
275	  };
276	  const deliverNotice = async (
277	    entry: ScheduledMonitor,
278	    options: { possibleDuplicate?: boolean } = {},
279	  ): Promise<boolean> => {
280	    const record = await entry.cycles.inspect(entry.cycleId);
281	    const monitor = record.monitors?.find((candidate) => candidate.attemptId === entry.attemptId);
282	    const notice = monitor?.notice;
283	    if (!monitor || !notice || notice.state !== "pending") return false;
284	    // Deliver only into the originating session; foreign/detached origins keep the pending notice.
285	    if (shuttingDown || monitor.originSessionId !== entry.sessionId) return false;
286	    try {
287	      pi.sendMessage(
288	        {
289	          customType: COMPLETION_NOTICE_TYPE,
290	          content: `${completionNoticeText({
291	            cycleId: entry.cycleId,
292	            attemptId: entry.attemptId,
293	            runId: monitor.runId,
294	            outcome: notice.outcome,
295	            processing: notice.processing,
296	          })}${options.possibleDuplicate ? " This notice was re-sent after an explicit resume because its earlier delivery could not be confirmed; it may duplicate an earlier report and still describes the same single run." : ""}`,
297	          display: true,
298	          details: {
299	            noticeId: notice.id,
300	            cycleId: entry.cycleId,
301	            attemptId: entry.attemptId,
302	            runId: monitor.runId,
303	            outcome: notice.outcome,
304	            processing: notice.processing,
305	            ...(options.possibleDuplicate ? { possibleDuplicate: true } : {}),
306	          },
307	        },
308	        { triggerTurn: true, deliverAs: "followUp" },
309	      );
