411	      const updated = await cycles.updateMonitor(cycleId, attemptId, (monitor) => {
412	        monitor.gets += 1;
413	        monitor.consecutiveTransientErrors = 0;
414	        monitor.lastSuccessAt = new Date().toISOString();
